class MeshSet:
    def __init__(self):
        self.verts = []     # list of (N,3) arrays
        self.faces = []     # list of index lists (global)
        self.cols = []
        self.lit = []
        self._nv = 0        # running vertex count

    def add(self, verts, faces, color, lit=True):
        verts = np.asarray(verts, float)
        base = self._nv
        self.verts.append(verts)
        for f in faces:
            self.faces.append([k + base for k in f])
            self.cols.append(np.asarray(color, float))
            self.lit.append(lit)
        self._nv += len(verts)

    def combine(self, other):
        base = self._nv
        for v in other.verts:
            self.verts.append(v)
        self._nv += sum(len(v) for v in other.verts)
        for f in other.faces:
            self.faces.append([k + base for k in f])
        for c in other.cols:
            self.cols.append(c)
        for l in other.lit:
            self.lit.append(l)

